    }
  } catch (error) {
    const result = new Error('ORIGINAL_MERCHANT_LISTENER_UNAVAILABLE'); result.code = error.code; throw result;
  } finally {
    await Promise.all(reservations.map(server => new Promise(done => server.close(done))));
  }
