  try {
    handle = await open(temporary, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | constants.O_NOFOLLOW, mode);
    if (uid !== undefined || info) await handle.chown(uid ?? info.uid, gid ?? info.gid);
