}

export const maintenanceFragment = (p, id) => `${p.publicOrigin} {\n  header Cache-Control "no-store"\n  header Retry-After "60"\n  header X-Stellar-Forge-Maintenance "${id}"\n  respond "Merchant maintenance" 503\n}\n`;
// This directive takes its whole raw path, unlike ExecStart word lists. Quoting
// it makes systemd ignore the condition as non-absolute (even with exit code 0).
export const guardText = marker => '[Unit]\nConditionPathExists=!' + absolute(marker).replaceAll('%', '%%') + '\n';

export function createLinuxHost(plan) {
  need(process.platform === 'linux' && process.getuid?.() === 0, 'Run host maintenance as the existing Linux host administrator');
  const { p, caddy, binaries, systemdDirectory } = plan;
  const command = async (binary, args, timeout = 330000) => {
    try { return (await exec(binary, args, { timeout, maxBuffer: 1024 * 1024,
      env: { PATH: process.env.PATH, LANG: 'C.UTF-8' }, shell: false })).stdout; }
    catch { throw new Error('HOST_COMMAND_FAILED: ' + binary + ' ' + args[0]); }
  };
  const ctl = (...args) => command(binaries.systemctl, args);
  async function states(units = plan.units) {
    const output = await ctl('show', '--property=Id,LoadState,ActiveState,SubState,MainPID,ControlPID,FragmentPath,DropInPaths,User,Group,DynamicUser', '--', ...units);
    const records = output.trim().split(/\n\s*\n/).map(block => Object.fromEntries(block.split('\n').filter(Boolean).map(line => {
      const n = line.indexOf('='); return [line.slice(0, n), line.slice(n + 1)];
    })));
    return units.map(unit => { const record = records.find(r => r.Id === unit);
      need(record && record.LoadState === 'loaded', 'Original host unit not loaded: ' + unit);
      return { ...record, MainPID: Number(record.MainPID ?? 0), ControlPID: Number(record.ControlPID ?? 0) };
    });
  }
  const stopped = rows => rows.every(r => ['inactive','failed'].includes(r.ActiveState) && r.MainPID === 0 && r.ControlPID === 0);
  async function assertStopped() { need(stopped(await states()), 'Owned writer group has not stopped'); }
  const dropin = unit => join(systemdDirectory, unit + '.d', '90-stellar-forge-maintenance.conf');
  async function guards(units, marker, present) {
    for (const unit of units) {
      const file = dropin(unit), text = guardText(marker);
      if (present) {
        try { await mkdir(dirname(file), { mode: 0o755 }); } catch (error) { if (error.code !== 'EEXIST') throw error; }
        await atomicFile(file, text, { allowed: [null, digest(text)], mode: 0o644 });
      } else await removeOwned(file, digest(text));
    }
    await ctl('daemon-reload');
  }
  async function reloadProxy() {
    const live = (await states([caddy.unit]))[0]; need(live.ActiveState === 'active', 'Existing shared Caddy service must be active');
    await command(caddy.binary, ['validate','--adapter','caddyfile','--config',caddy.config], 60000);
    await command(caddy.binary, ['reload','--adapter','caddyfile','--config',caddy.config], 60000);
  }
  async function publicRequest(path) {
    const response = await fetch(p.publicOrigin + path, { redirect: 'error', signal: AbortSignal.timeout(10000) });
    await response.body?.cancel(); return response;
  }
  async function account(name) {
    const entry = (await command(binaries.getent, ['passwd',name], 10000)).trim().split(':');
    const uid = Number(entry[2]);
    need(entry.length >= 7 && Number.isSafeInteger(uid) && uid >= 0, 'Resolve the existing service account: ' + name);
    return uid;
  }
  async function writerFiles(writers, restore = false) {
    for (const file of writers.files) {
      const bytes = restore ? Buffer.from(file.original.bytesBase64, 'base64') : await regular(file.candidate);
      need(digest(bytes) === (restore ? file.original.sha256 : file.sha256), 'Retained writer bytes changed: ' + file.path);
      await atomicFile(file.path, bytes, { allowed: [file.original.sha256, ...(file.sha256 ? [file.sha256] : [])],
        mode: file.original.mode, uid: file.original.uid, gid: file.original.gid });
    }
    await ctl('daemon-reload');
  }
  return {
    states, assertStopped,
    async validateInstalled() {
      const rows = await states();
      for (const name of plan.ownUnits) {
        const row = rows.find(r => r.Id === name), installed = join(systemdDirectory, name);
        need(row.FragmentPath === installed && !row.DropInPaths, 'Use the original generated unit without untracked overrides: ' + name);
        need(digest(await regular(installed)) === p.artifacts[name], 'Installed unit differs from its deployment bundle: ' + name);
      }
      need(digest(await regular(caddy.fragment)) === p.artifacts.Caddyfile, 'Imported Caddy fragment differs from the original bundle');
      need(rows.filter(r => plan.ownUnits.includes(r.Id)).every(r => r.ActiveState === 'active'), 'Start from the running original merchant component group');
      return rows;
    },
    async validateWriters(templates, rows) {
      const merchantUid = await account(p.serviceUser);
      for (const unit of templates.units) {
        const row = rows.find(record => record.Id === unit), files = templates.files.filter(file => file.unit === unit);
        const installed = join(systemdDirectory, unit);
        const dropins = files.map(file => file.path).filter(file => file !== installed).sort();
        need(row?.FragmentPath === installed && row.DropInPaths === dropins.join(' '),
          'Loaded writer fragment/drop-ins differ from the pinned files: ' + unit);
        if (/\.(service|socket)$/.test(unit)) {
          need(row.DynamicUser !== 'yes', 'Use the existing stable merchant/root account for a migrated writer: ' + unit);
          const uid = row.User ? await account(row.User) : 0;
          need(uid === 0 || uid === merchantUid, 'Writer must own the restored private state as the existing merchant account: ' + unit);
        }
      }
    },
    async pause(id, expectedFragments) {
      const text = maintenanceFragment(p, id);
      await atomicFile(caddy.fragment, text, { allowed: [...expectedFragments, digest(text)], mode: 0o644 });
      await reloadProxy();
      const deadline = Date.now() + 15000;
      do {
        try {
          const response = await publicRequest('/_seller/openapi.json');
          if (response.status === 503 && response.headers.get('x-stellar-forge-maintenance') === id) return;
        } catch { /* A proxy reload can close a previously pooled read connection. */ }
        await new Promise(done => setTimeout(done, 150));
      } while (Date.now() < deadline);
      throw new Error('Public ingress did not enter this operation\'s maintenance mode');
    },
    async expose(bundle, id) {
      const current = await checkBundle(bundle), text = await regular(join(bundle, 'Caddyfile'));
      await atomicFile(caddy.fragment, text, { allowed: [digest(maintenanceFragment(p, id)), current.artifacts.Caddyfile], mode: 0o644 });
      await reloadProxy();
    },
    guards,
    async stop() { await ctl('stop', '--', ...plan.units); await assertStopped(); },
    async install(bundle, previousCandidate) {
      const next = await checkBundle(bundle);
      const prior = previousCandidate ? await checkBundle(previousCandidate) : null;
      need(next.merchant === p.merchant && next.publicOrigin === p.publicOrigin && next.kind === p.kind && next.mode === p.mode &&
        next.serviceUser === p.serviceUser && next.serviceGroup === p.serviceGroup &&
        JSON.stringify(next.services.map(s => s.unit)) === JSON.stringify(p.services.map(s => s.unit)), 'Restored host changes the merchant/service identity');
      await command(binaries.systemdAnalyze, ['verify','--man=no',...plan.ownUnits.map(name => join(bundle, name))], 60000);
      for (const name of plan.ownUnits) await atomicFile(join(systemdDirectory, name), await regular(join(bundle, name)),
        { allowed: [p.artifacts[name], next.artifacts[name], ...(prior ? [prior.artifacts[name]] : [])], mode: 0o644 });
      await ctl('daemon-reload');
    },
    async installWriters(writers, bundle) {
      // Parse all selected fragments with their original drop-ins before any
      // writer is restarted. Staged paths preserve the systemd unit hierarchy.
      await command(binaries.systemdAnalyze, ['verify','--man=no',
        ...plan.ownUnits.map(name => join(bundle, name)),
        ...writers.units.map(name => join(writers.directory, 'units', name))], 60000);
      await writerFiles(writers);
    },
    async restoreWriters(templates, candidate) { await writerFiles(candidate ?? templates, true); },
    async grantRestoredAccess(destination, candidate) {
      const pw = (await command(binaries.getent, ['passwd',p.serviceUser], 10000)).trim().split(':');
      const group = (await command(binaries.getent, ['group',p.serviceGroup], 10000)).trim().split(':');
      const uid = Number(pw[2]), gid = Number(group[2]);
      need(pw[0] === p.serviceUser && group[0] === p.serviceGroup && Number.isSafeInteger(uid) && uid > 0 && Number.isSafeInteger(gid) && gid > 0,
        'Original unprivileged service account and group must exist');
      let entries = 0;
      const walk = async (file, rootOwned = false) => {
        need(++entries <= 22000, 'Restored host exceeds original recovery file limit');
        const st = await lstat(file);
        need(!st.isSymbolicLink() && (st.isDirectory() || st.isFile() && st.nlink === 1), 'Unsafe restored host entry');
        const control = rootOwned || file === candidate.bundle || file === candidate.planFile || file === candidate.writers?.directory;
        await chown(file, control ? 0 : uid, gid); await chmod(file, st.isDirectory() ? control ? 0o750 : 0o700 : control ? 0o640 : 0o600);
        if (st.isDirectory()) for (const child of await readdir(file)) await walk(join(file, child), control);
      };
      // Only the newly created destination is changed; original source/state stay intact.
      for (const child of await readdir(destination)) await walk(join(destination, child));
      await chown(destination, 0, gid); await chmod(destination, 0o750);
      const next = await checkBundle(candidate.bundle);
      await command(binaries.runuser, ['-u',p.serviceUser,'-g',p.serviceGroup,'--',next.node,
        join(next.sourceRoot,'stellar/scf-starforge-20261009/sf99-merchant-deploy/cli.mjs'),'check','--bundle',candidate.bundle], 30000);
      if (candidate.writers) {
        const rows = await states(candidate.writers.units);
        for (const row of rows.filter(record => /\.(service|socket)$/.test(record.Id))) {
          if (!row.User || await account(row.User) === 0) continue;
          const user = (await command(binaries.getent, ['passwd',row.User], 10000)).trim().split(':');
          const group = (await command(binaries.getent, ['group',row.Group || user[3]], 10000)).trim().split(':');
          need(user[0] && group[0], 'Resolve the original external writer identity: ' + row.Id);
          const selected = candidate.writers.files.filter(file => file.unit === row.Id)
            .flatMap(file => file.changes.map(change => change.to));
          // Observe traversal under the writer's original account and group.
          // A future output path is checked through its nearest existing parent.
          const check = 'const fs=require("node:fs"),p=require("node:path");for(let f of JSON.parse(process.argv[1])){let s;'
            + 'for(;;){try{s=fs.statSync(f);break;}catch(e){if(e.code!=="ENOENT"||f===p.dirname(f))throw e;f=p.dirname(f);}}'
            + 'fs.accessSync(f,fs.constants.R_OK);fs.accessSync(s.isDirectory()?f:p.dirname(f),fs.constants.X_OK);}';
          await command(binaries.runuser, ['-u',user[0],'-g',group[0],'--',next.node,'-e',check,JSON.stringify(selected)], 30000);
        }
      }
    },
    async startReaders(bundle, marker) {
      const current = await checkBundle(bundle);
      const readers = current.services.filter(s => s.role !== 'delivery').map(s => s.unit);
      await guards(readers, marker, false);
      await ctl('start', '--', ...readers);
      const rows = await states(readers); need(rows.every(r => r.ActiveState === 'active' && r.MainPID > 0), 'Restored merchant reader services are not active');
    },
    async startOriginalGroup(originalStates, marker) {
      await guards(plan.units, marker, false);
      const active = originalStates.filter(r => r.ActiveState === 'active').map(r => r.Id);
      if (active.length) await ctl('start', '--', ...active);
      const rows = await states(active); need(rows.every(r => r.ActiveState === 'active'), 'Original active service group did not resume');
    },
    async smoke(bundle, publicOrigin = false) {
      const { smoke } = await import('./cli.mjs');
      const deadline = Date.now() + 30000;
      do {
        const result = await smoke(bundle, { publicOrigin });
        if (result.passed) return result;
        await new Promise(done => setTimeout(done, 250));
      } while (Date.now() < deadline);
      throw new Error('Original merchant readiness/public confinement check failed');
    },
  };
}

// MIT. Original merchant quiesce, encrypted recovery, restored-host activation.
import { mkdir, lstat } from 'node:fs/promises';
import { join } from 'node:path';
import { acquireDeliveryLease } from '../sf98-merchant-delivery/delivery-lock.mjs';
import { run as recover } from '../sf101-merchant-recovery/recover.mjs';
import { checkBundle } from './host.mjs';
import { prepareRestoredHost } from './restore-host.mjs';
import { loadWriterTemplates, prepareRestoredWriters } from './restore-writers.mjs';
import { loadMaintenance, createLinuxHost, atomicJSON, atomicFile, removeOwned, jsonFile,
  regular, digest, inside, absolute, need, privateDirectory, MAINTENANCE_SCHEMA } from './maintenance-system.mjs';

const OPERATION_SCHEMA = 'stellar-forge.merchant-maintenance-operation.v1';
const terminal = state => ['COMPLETE','ROLLED_BACK'].includes(state.phase);
const beforeCommit = state => !['COMMITTED','COMPLETE'].includes(state.phase);
const activeFile = plan => join(plan.operationsRoot, 'active-operation.json');
const markerFile = (plan, id) => join(plan.operationsRoot, id, 'paused');
const stateFile = (plan, id) => join(plan.operationsRoot, id, 'operation.json');
const idOf = id => { need(typeof id === 'string' && /^[A-Za-z0-9][A-Za-z0-9_.-]{0,79}$/.test(id), 'Stable operation ID required'); return id; };
const exists = async file => { try { await lstat(file); return true; } catch (error) { if (error.code === 'ENOENT') return false; throw error; } };
const stamp = () => new Date().toISOString();

async function save(plan, state, phase = state.phase) {
  state.phase = phase; state.updatedAt = stamp();
  await atomicJSON(stateFile(plan, state.id), state);
}
function summary(state) {
  return { merchant: state.merchant, operationId: state.id, command: state.command, phase: state.phase,
    snapshot: state.snapshot ?? null, restoredHost: state.candidate ? { bundle: state.candidate.bundle,
      planFile: state.candidate.planFile, stateRoot: state.candidate.stateRoot, summary: state.candidate.summary } : null,
    activeBundle: state.phase === 'COMPLETE' ? state.candidate?.bundle ?? state.originalBundle : state.phase === 'ROLLED_BACK' ? state.originalBundle : null,
    nextMaintenancePlan: terminal(state) ? state.phase === 'COMPLETE' ? state.nextPlan ?? state.maintenancePlan : state.maintenancePlan : null,
    createdAt: state.createdAt, updatedAt: state.updatedAt,
    ...(state.lastError ? { lastError: state.lastError } : {}), paidRequestsExecuted: 0 };
}
async function ownedState(plan, id) {
  const state = await jsonFile(stateFile(plan, id));
  need(state.schema === OPERATION_SCHEMA && state.id === id && state.merchant === plan.p.merchant &&
    state.planDigest === plan.planDigest && state.recoveryDigest === plan.recoveryDigest,
    'Resume with this operation\'s unchanged original maintenance and recovery plans');
  return state;
}
async function clearActive(plan, state) {
  const file = activeFile(plan);
  if (await exists(file)) {
    const bytes = await regular(file), current = JSON.parse(bytes);
    need(current.id === state.id, 'Another maintenance operation owns this host');
    await removeOwned(file, digest(bytes));
  }
}

async function begin(plan, host, { id, command, destination, sourceRoot }) {
  const active = activeFile(plan);
  if (await exists(active)) {
    const previous = await jsonFile(active);
    const prior = await jsonFile(stateFile(plan, idOf(previous.id)));
    need(prior.schema === OPERATION_SCHEMA && prior.id === previous.id && prior.merchant === plan.p.merchant,
      'Unexpected original operation pointer');
    need(terminal(prior), 'An unfinished operation already owns this host; resume or roll back ' + previous.id);
    await clearActive(plan, prior);
  }
  if (command === 'migrate') {
    destination = absolute(destination, 'new restored host destination');
    need(!await exists(destination), 'Restored host destination must be new');
    for (const directory of [plan.operationsRoot, plan.p.sourceRoot, plan.p.bundle, ...plan.recovery.roots.map(r => r.path)])
      need(!inside(directory, destination) && !inside(destination, directory), 'Restored destination overlaps an original host component');
    if (sourceRoot !== undefined) absolute(sourceRoot, 'selected immutable source release');
  } else need(destination === undefined && sourceRoot === undefined, 'Backup does not select a restored host destination');
  need(typeof process.env[plan.passphraseEnv] === 'string' && Buffer.byteLength(process.env[plan.passphraseEnv]) >= 16,
    'Supply the original SF101 private passphrase environment before starting maintenance');
  const originalStates = await host.validateInstalled();
  const writerTemplates = command === 'migrate' ? await loadWriterTemplates(plan) : null;
  if (writerTemplates?.units.length) await host.validateWriters(writerTemplates, originalStates);
  const directory = join(plan.operationsRoot, id);
  await mkdir(directory, { mode: 0o700 });
  const state = { schema: OPERATION_SCHEMA, id, merchant: plan.p.merchant, command,
    maintenancePlan: plan.file, planDigest: plan.planDigest, recoveryDigest: plan.recoveryDigest,
    originalBundle: plan.p.bundle, originalStates, writerTemplates, destination, sourceRoot: sourceRoot ?? plan.p.sourceRoot,
    phase: 'PREPARED', createdAt: stamp(), updatedAt: stamp(), snapshots: [], restoreAttempts: [] };
  // Retain the exact original inputs for an operator after a machine interruption.
  await atomicFile(join(directory, 'original-host-plan.json'), await regular(plan.p.planFile));
  await atomicFile(join(directory, 'recovery-plan.json'), await regular(plan.recoveryPlan));
  await atomicFile(markerFile(plan, id), id + '\n');
  await save(plan, state);
  await atomicJSON(active, { schema: OPERATION_SCHEMA, merchant: state.merchant, id });
  return state;
}

async function leaseOutbox(directory) {
  if (!directory || !await exists(directory)) return null;
  return await acquireDeliveryLease(directory, { purpose: 'drain' });
}
async function requiredOutboxLease(p) {
  if (p.kind === 'release') return null; // Original SF82 has no SF98 outbox writer.
  const lease = await leaseOutbox(p.outbox);
  need(lease || !p.delivery && p.mode === 'challenge', 'Original native/delivery outbox is missing: ' + p.outbox);
  return lease;
}
async function rollback(plan, host, state) {
  need(beforeCommit(state), 'This operation committed its restored state; resume it or migrate forward from that active state');
  state.rollbackRequested = true; await save(plan, state);
  const marker = markerFile(plan, state.id);
  const fragments = [plan.p.artifacts.Caddyfile];
  if (state.candidate) fragments.push((await checkBundle(state.candidate.bundle)).artifacts.Caddyfile);
  await host.pause(state.id, fragments);
  await host.guards(plan.units, marker, true);
  await host.stop();
  let originalLease, candidateLease;
  try {
    originalLease = await requiredOutboxLease(plan.p);
    if (state.candidate) {
      const candidate = await checkBundle(state.candidate.bundle);
      // A damaged/incomplete candidate must not prevent recovery of the intact
      // original. Any existing candidate queue is still exclusively held.
      if (candidate.outbox !== plan.p.outbox) candidateLease = await leaseOutbox(candidate.outbox);
    }
    await host.install(plan.p.bundle, state.candidate?.bundle);
    if (state.writerTemplates?.units.length) await host.restoreWriters(state.writerTemplates, state.candidate?.writers);
  } finally { await candidateLease?.release(); await originalLease?.release(); }
  await host.startOriginalGroup(state.originalStates, marker);
  await host.smoke(plan.p.bundle);
  await host.expose(plan.p.bundle, state.id);
  await host.smoke(plan.p.bundle, true);
  await removeOwned(marker, digest(state.id + '\n'));
  await save(plan, state, 'ROLLED_BACK'); await clearActive(plan, state);
  return summary(state);
}

async function continueOperation(plan, host, state) {
  if (terminal(state)) { await clearActive(plan, state); return summary(state); }
  if (state.rollbackRequested) return rollback(plan, host, state);
  const marker = markerFile(plan, state.id), directory = join(plan.operationsRoot, state.id);
  let originalLease = null, restoredLease = null;
  const release = async () => {
    await restoredLease?.release(); restoredLease = null;
    await originalLease?.release(); originalLease = null;
  };
  try {
    if (beforeCommit(state)) {
      // Resume reasserts the actual paused surface and kernel/process state. A
      // journal phase alone is never substituted for stopping the owned writers.
      await host.pause(state.id, [plan.p.artifacts.Caddyfile]);
      await host.guards(plan.units, marker, true);
      await host.stop();
      originalLease = await requiredOutboxLease(plan.p);
      await host.assertStopped();
      if (state.phase === 'PREPARED') await save(plan, state, 'QUIESCED');
    }
    if (state.phase === 'QUIESCED') {
      const out = join(directory, 'snapshot-' + (state.snapshots.length + 1));
      state.snapshots.push(out); await save(plan, state);
      const snapshot = await recover(['snapshot','--plan',join(directory,'recovery-plan.json'),'--out',out,
        '--pass-env',plan.passphraseEnv,'--quiesced']);
      const verified = await recover(['verify','--bundle',out,'--pass-env',plan.passphraseEnv]);
      need(snapshot.status === 'SNAPSHOT_CREATED' && verified.status === 'SNAPSHOT_VERIFIED', 'Original encrypted snapshot was not verified');
      await host.assertStopped();
      state.snapshot = { ...snapshot, verified: true }; await save(plan, state, 'SNAPSHOT');
    }
    if (state.phase === 'SNAPSHOT' && state.command === 'migrate') {
      const attempt = state.restoreAttempts.length;
      const destination = attempt === 0 ? state.destination : state.destination + '.resume-' + attempt;
      need(attempt < 32, 'Review retained interrupted destination attempts before another recovery');
      state.restoreAttempts.push(destination); await save(plan, state);
      const restoreHost = host.prepareRestoredHost ?? prepareRestoredHost;
      state.candidate = await restoreHost({ previousBundle: plan.p.bundle,
        recoveryPlan: join(directory,'recovery-plan.json'), snapshot: state.snapshot.bundle,
        passphraseEnv: plan.passphraseEnv, destination, sourceRoot: state.sourceRoot });
      for (const field of ['bundle','planFile','stateRoot']) need(inside(destination, absolute(state.candidate[field])),
        'Restored host result leaves its new destination: ' + field);
      if (state.writerTemplates?.units.length) state.candidate.writers = await prepareRestoredWriters({
        templates: state.writerTemplates, mappings: state.candidate.mappings, destination });
      state.activeDestination = destination; await save(plan, state, 'RESTORED');
    }
    if (state.phase === 'RESTORED') {
      await host.grantRestoredAccess(state.activeDestination, state.candidate);
      await host.install(state.candidate.bundle);
      if (state.candidate.writers) await host.installWriters(state.candidate.writers, state.candidate.bundle);
      await save(plan, state, 'INSTALLED');
    }
    if (state.phase === 'INSTALLED') {
      const next = await checkBundle(state.candidate.bundle);
      restoredLease = await requiredOutboxLease(next);
      await host.startReaders(state.candidate.bundle, marker);
      state.readiness = await host.smoke(state.candidate.bundle);
      await save(plan, state, 'READY');
    } else if (state.phase === 'READY') {
      const next = await checkBundle(state.candidate.bundle);
      restoredLease = await requiredOutboxLease(next);
      await host.startReaders(state.candidate.bundle, marker);
      state.readiness = await host.smoke(state.candidate.bundle);
    }
    if (state.phase === 'READY' || state.phase === 'SNAPSHOT' && state.command === 'backup') {
      // External delivery may resume immediately after this durable transition.
      // From here every retry repairs forward against the chosen active state.
      if (state.candidate) {
        state.nextPlan = join(state.activeDestination, 'maintenance.json');
        const roots = state.candidate.mappings.map(mapping => ({ name: mapping.name, path: mapping.to }));
        const distinct = roots.filter((root, index) => !roots.some((other, otherIndex) => otherIndex !== index &&
          inside(other.path, root.path) && (other.path !== root.path || otherIndex < index)));
        const recoveryPlan = join(state.activeDestination, 'recovery-plan.json');
        await atomicJSON(recoveryPlan, { schema: 'stellar-forge.merchant-recovery-plan.v1', roots: distinct });
        const next = { ...plan.raw, bundle: state.candidate.bundle, recoveryPlan,
          ...(state.candidate.writers ? { writerTemplates: state.candidate.writers.nextTemplates } : {}) };
        await atomicJSON(state.nextPlan, host.nextMaintenancePlan ? await host.nextMaintenancePlan(state, next) : next);
      }
      await save(plan, state, 'COMMITTED');
    }
    if (state.phase === 'COMMITTED') {
      const bundle = state.candidate?.bundle ?? plan.p.bundle;
      await release();
      await host.startOriginalGroup(state.originalStates, marker);
      await host.smoke(bundle);
      await host.expose(bundle, state.id);
      state.publicReadiness = await host.smoke(bundle, true);
      await removeOwned(marker, digest(state.id + '\n'));
      delete state.lastError;
